  "ev.hsn6": "আইটেম {n}: ই-ইনভয়েসে 6 বা 8 সংখ্যার HSN/SAC কোড লাগবে (4 সংখ্যা শুধু ₹5 কোটির কম বিজনেসের জন্য, যারা ই-ইনভয়েস করে না)।",
  "ev.old30": "এই ইনভয়েস 30 বা তার বেশি দিনের পুরনো। ₹10 কোটি বা বেশি টার্নওভারে পোর্টাল এটা আর রেজিস্টার করে না। নতুন ইনভয়েস বানানোর আগে আপনার অ্যাকাউন্ট্যান্টকে জিজ্ঞেস করুন।",
  "ev.lt5": "ই-ইনভয়েস আপনার জন্য বাধ্যতামূলক নয়, যদি না 2017-18 থেকে কোনো বছর আপনার টার্নওভার ₹5 কোটি পার করে থাকে।",
  "ev.old180": "180 দিনের বেশি পুরনো ডকুমেন্টের ই-ওয়ে বিল পোর্টাল বানায় না।",
  "ev.smallst": "{st}-এর ভেতরে ই-ওয়ে বিল সাধারণত ₹{v}-এর বেশি হলেই লাগে (অন্য রাজ্যে ₹50,000-এর বেশি; অন্য রাজ্যে যাওয়া জব ওয়ার্ক আর হস্তশিল্পে যেকোনো মূল্যে লাগে)।",
  "ev.fromirn": "আপনার বিজনেসকে ই-ইনভয়েস বানাতে হলে, এই ইনভয়েসের ই-ওয়ে বিল পোর্টাল শুধু এর IRN থেকে বানায়: “ই-ইনভয়েসের সাথে ই-ওয়ে বিলও বানান”-এ টিক দিন আর ই-ইনভয়েস ফাইল বানান।",
