  "ei.rmnote": "আপনি এই IRN পোর্টালে ক্যানসেল করে থাকলে, এই ইনভয়েস নম্বর আর কখনো রেজিস্টার হবে না। সঠিক ইনভয়েস নতুন নম্বরে বানান।",
