  "td.nopan": "বৈধ PAN না থাকলে রেট হয় 20% বা স্বাভাবিক রেটের দ্বিগুণ, যেটা বেশি (মাল কেনায় 5%)। প্রাপকের কাছে PAN চেয়ে নিন।",
  "td.trans": "যে ট্রান্সপোর্টারের 10টি বা তার কম মালবাহী গাড়ি আছে এবং PAN সহ ঘোষণা দেন, তাঁকে TDS ছাড়া পেমেন্ট করা যায়।",
  "td.q": "কাটবেন শুধু যদি গত বছর আপনার টার্নওভার ₹10 কোটির বেশি ছিল, এবং শুধু এই বিক্রেতার কাছ থেকে বছরের কেনার যে অংশ ₹50 লাখের ওপরে তার ওপর।",
  "td.ib": "ট্যাক্স অডিটের আওতায় নন এমন ব্যক্তির দেওয়া ভাড়ায় TDS একবারই কাটা হয়, বছরের বা ভাড়াচুক্তির শেষ মাসের ভাড়া থেকে।",
