  "b1.v_tcs": "TCS রেট লিখুন, বা TCS-এর টিক তুলে দিন।",
  "b1.v_tcs10": "গাড়ি বা নোটিফায়েড জিনিসে TCS তখনই লাগে যখন একটি আইটেমের দাম ₹10 লাখের বেশি (নোটিফিকেশন 36/2025 নিয়ে CBDT FAQ, 23 এপ্রিল 2025)। এই বিলের কোনো আইটেম তেমন নয়। TCS-এর টিক সরান।",
  "b1.c_tcs10g": "GST ছাড়া কোনো আইটেম ₹10 লাখের বেশি নয়, শুধু GST যোগ করলে বেশি। অ্যাক্টে \"ভ্যালু\" লেখা আছে এবং এই লিমিটে GST ধরা হবে কি না তা কোনো সার্কুলার ঠিক করেনি। এই বিলে কি TCS নেবেন?",
  "b1.tcsbh": "CBDT সার্কুলার 17/2020 (প্যারা 4.6.1, পুরোনো সেকশন 206C-এর জন্য): TCS পাওয়া টাকার উপর GST সহ নেওয়া হয়, GST, ডিসকাউন্ট বা রিটার্নের জন্য কিছু বাদ যায় না। ট্যাক্সেবল ভ্যালু শুধু আপনার CA বললে তবেই বেছে নিন।",
  "b1.cntcs": "বিল {no}-এ {v} TCS ছিল। এই ক্রেডিট নোট সেই TCS কমায় না: CBDT সার্কুলার 17/2020 (প্যারা 4.6.1) অনুযায়ী সেলস রিটার্নে কোনো অ্যাডজাস্টমেন্ট নেই। ক্রেতা এই TCS নিজের ইনকাম ট্যাক্স রিটার্নে ক্লেম করেন।",
