  "b2.gain": "লাভ {a}: অ্যাকাউন্ট্যান্টকে জিজ্ঞেস করুন",
  "b2.farules": "ডেপ্রিসিয়েশন কীভাবে হিসাব হয়",
  "b2.farule1": "খাতার ডেপ্রিসিয়েশন কোম্পানিজ অ্যাক্ট, 2013 এর শিডিউল II অনুযায়ী: প্রতিটি ধরনের অ্যাসেটের একটা কাজের আয়ু আছে (যেমন কম্পিউটার 3 বছর, ফার্নিচার 10 বছর, প্ল্যান্ট ও মেশিনারি 15 বছর, গাড়ি 8 বছর), বাকি ভ্যালু সাধারণত দামের 5% এর বেশি হয় না, আর বছরের মাঝে যোগ বা বিক্রি হওয়া অ্যাসেটে শুধু ব্যবহারের দিনগুলোর ডেপ্রিসিয়েশন লাগে। স্ট্রেট লাইন (SLM: প্রতি বছর সমান টাকা) বা রিটেন ডাউন ভ্যালু (WDV: বাকি টাকার উপর নির্দিষ্ট রেট) বেছে নিন। প্রোপ্রাইটর আর ফার্ম প্রায়ই এই পদ্ধতিই নেয়; সিদ্ধান্ত নেন আপনার অ্যাকাউন্ট্যান্ট।",
  "b2.farule2": "ইনকাম ট্যাক্স ডেপ্রিসিয়েশন প্রতিটি ব্লকের আলাদা হিসাব হয়: ব্লক রেটে রিটেন ডাউন ভ্যালু (যেমন প্ল্যান্ট ও মেশিনারি 15%, ফার্নিচার 10%, কম্পিউটার 40%), বছরে 180 দিনের কম ব্যবহৃত অ্যাসেটে অর্ধেক রেট, আর বিক্রির টাকা ব্লক থেকে কমে। এটা শুধু ইনকাম ট্যাক্স রিটার্নের জন্য, খাতায় কখনো তোলা হয় না। ভরা রেটগুলো সাধারণ ব্লক রেট: আপনার অ্যাকাউন্ট্যান্টের কাছে নিশ্চিত হন, বিশেষ করে 1 এপ্রিল 2026 থেকে ইনকাম-ট্যাক্স অ্যাক্ট, 2025 এর বছরগুলোর জন্য।",
  "b2.farule3": "আপনি 'ডেপ্রিসিয়েশন তুলুন' চাপলে তবেই ডেপ্রিসিয়েশন খাতায় যায়: বছরের শেষ দিনের (বা বছরের মাঝে আজকের) জার্নাল এন্ট্রি ডেপ্রিসিয়েশনকে ডেবিট করে আর প্রতিটি অ্যাসেট কমায়। পরে অ্যাসেট বদলালে আবার তুলুন, শুধু পার্থক্য যোগ হবে।",
