  "hp.items": "প্রতিটি আইটেম বা সার্ভিসের এক লাইন। সেভ করা আইটেম বাছলে রেট, HSN আর GST ভরে যায়, বা নতুন লিখুন। পরিমাণ × রেট থেকে ডিসকাউন্ট বাদ দিয়ে ট্যাক্সেবল ভ্যালু হয়।",
  "hp.notes": "শর্ত, ব্যাংকের বিবরণ আর ছাপা পাতার চেহারা। পরের বারের জন্য ডিফল্ট হিসেবে সেভ হয়।",
  "hp.einv": "যেসব বিজনেসের ই-ইনভয়েস বা ই-ওয়ে বিল বানানো বাধ্যতামূলক: ফাইল ডাউনলোড করুন, সরকারি পোর্টালে নিজের লগইনে আপলোড করুন, তারপর উত্তর এখানে লোড করুন।",
  "hp.exp": "এক্সপোর্টের জন্য: শিপিং বিল, পোর্ট আর কারেন্সি। এক্সপোর্ট জিরো-রেটেড: LUT থাকলে GST লাগে না; না থাকলে IGST দিয়ে রিফান্ড পাওয়া যায়।",
  "hp.s.from": "যিনি আপনাকে টাকা দিয়েছেন। সেভ করা কাস্টমার বাছুন বা নাম লিখুন।",
  "hp.s.pay": "টাকার অঙ্ক, তারিখ আর কীভাবে দেওয়া। আইনের সীমার বেশি ক্যাশে সতর্কবার্তা আসে।",
  "hp.s.to": "যাকে আপনি টাকা দিয়েছেন। সেভ করা সাপ্লায়ার বাছুন বা নাম লিখুন।",
  "hp.s.lines": "টাকা কীসের জন্য, প্রত্যেকটার এক লাইন (যেমন ভাড়া, মেরামত, গাড়িভাড়া)।",
  "hp.s.tdsrcm": "এই পেমেন্ট থেকে TDS কাটলে, বা রিভার্স চার্জে GST আপনাকে দিতে হলে ভরুন।",
  "hp.s.sign": "যিনি দিলেন, নিলেন আর অনুমোদন করলেন তাঁদের নাম। হাতে সই করতে চাইলে খালি রাখুন।",
  "hp.s.tenant": "ভাড়া কে দেন আর প্রপার্টির ঠিকানা।",
  "hp.s.landlord": "ভাড়া কে পান। HRA ক্লেমের জন্য বছরের ভাড়া ₹1 লাখের বেশি হলে বাড়িওয়ালার PAN লাগে।",
  "hp.s.rent": "মাসের ভাড়া আর কোন কোন মাস। প্রতি মাসের একটা রসিদ তৈরি হয়।",
