  "hp.s.employer": "আপনার বিজনেসের বিবরণ, যেমন স্লিপে ছাপা হয়।",
  "hp.s.att": "মাসের দিন আর যে দিনগুলোর মাইনে হয়। বিনা বেতনের ছুটির মাইনে কাটা যায়।",
