  "hp.s.ded": "PF, ESI, প্রফেশনাল ট্যাক্স, TDS আর অন্য কাটা। বোতাম এগুলো নিজে হিসাব করতে পারে।",
  "hp.s.entries": "প্রতিটি ছোট ক্যাশ খরচ বা টপ-আপ, এক-এক লাইন। চলতি ব্যালান্স বলে বাক্সে কত থাকা উচিত।",
  "hp.a.home": "আজকের ঝলক: পাওনা আর দেনা টাকা, বাকি পড়া বিল আর নতুন এন্ট্রি।",
  "hp.a.sales": "প্রতিটি সেল আর প্রতিটি বিলে কত বাকি। কোটেশন বা অর্ডার এখানেই বিলে বদলান।",
