  "hp.a.money": "আসা আর যাওয়া টাকা। প্রতিটি পেমেন্ট তার বিলের সঙ্গে জুড়ুন; বাকিটা সবচেয়ে পুরোনো বিলে যায়।",
  "hp.a.dues": "কে আপনাকে দেবে আর আপনি কাকে দেবেন, বিলের বয়স অনুযায়ী। এখান থেকেই ভদ্র WhatsApp রিমাইন্ডার পাঠান।",
  "hp.a.parties": "প্রতিটি কাস্টমার আর সাপ্লায়ারের ব্যালান্স। স্টেটমেন্টের জন্য খুলুন।",
  "hp.a.cash": "আপনার এন্ট্রি থেকে হিসাব করা হাতের ক্যাশ আর ব্যাংক ব্যালান্স।",
